function checkAnswer(s){const val=s.options?[...selected].sort().join(''):$('#answer').value.trim().replace(/\s/g,'').toLowerCase();if(!val){$('#feedback').innerHTML='<div class="feedback wrong">請先選擇或輸入答案。</div>';return}const correct=s.options?val===s.answer:s.answers.some(a=>a.toLowerCase()===val);if(!correct){$('#feedback').innerHTML=`<div class="feedback wrong">再觀察一次。${s.listening?'重新播放音檔，留意工作或安全行為。':'回到上方教材，找出支持答案的句子。'}${s.multi?' 這一關需要選出兩項。':''}</div>`;return}if(!unlocked(s))return;const reviewing=completed.has(s.id);completed.add(s.id);persist();updateProgress();const next=currentTask();const instruction=reviewing?'複習完成，原有闖關進度已保留。':next?'下一站：'+String(next.id).padStart(2,'0')+' '+next.title+' · '+next.area:'下一站：安全出口。請準備研究手冊中的兩組密碼。';$('#feedback').innerHTML=`<div class="feedback"><b>✓ 觀察任務完成${s.code?` · 取得密碼 ${s.code}`:' · 獲得棲地守護徽章'}</b><br>${s.explain}${s.transcript?`<details><summary>查看聽力逐字稿</summary><p lang="en">${s.transcript}</p></details>`:''}</div><div class="next-instruction"><b>${reviewing?'複習完成':'新路線已解鎖'}</b><p>${instruction}</p><small>${reviewing?'返回探索後，可以繼續目前關卡或重讀其他已完成任務。':'按下出發後會沿路線步行到下一站；也可關閉面板，自行跟隨箭頭。'}</small></div><button class="primary" id="continueBtn" style="margin-top:14px">${reviewing?'返回探索 →':'返回農場，步行前往 →'}</button>`;$('#continueBtn').onclick=closePanel;taskFlow?.complete();$('#submitAnswer').disabled=true;$('#feedback').scrollIntoView({behavior:'smooth',block:'nearest'})}
