$('#startBtn').onclick=()=>{started=true;document.body.classList.add('playing');background.start();$('#welcome').hidden=true;rebuildRoute();toast(completed.size?'歡迎回來，已接續你的探索位置。':'依箭頭自行走到第一關，抵達後按 Observe。')};if(completed.size)$('#resumeNote').textContent=`已找到這台裝置的進度：${completed.size} / 11 任務，開始後會繼續保留。`;
// Touch and mouse navigation: no pointer lock, so iPad and phone use the same camera.
let mouseForward=false,suppressCanvasClick=false,drag=null;canvas.addEventListener('click',e=>{if(e.pointerType!=='mouse'||!started||modal||suppressCanvasClick)return;mouseForward=!mouseForward;toast(mouseForward?'滑鼠前進中 · 再按左鍵停止':'已停止前進')});canvas.addEventListener('pointerdown',e=>{if(!started||modal)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};stopAuto();drag.startX=e.clientX;drag.startY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||modal)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>8)drag.moved=true;const sensitivity=e.pointerType==='touch'?.004:.003;yaw=normalizeYaw(yaw-(e.clientX-drag.x)*sensitivity);pitch=Math.max(-1.1,Math.min(.8,pitch-(e.clientY-drag.y)*sensitivity));drag.x=e.clientX;drag.y=e.clientY});const stopDrag=()=>{if(drag?.moved){suppressCanvasClick=true;setTimeout(()=>suppressCanvasClick=false,0)}drag=null};canvas.addEventListener('pointerup',stopDrag);canvas.addEventListener('pointercancel',stopDrag);
let joyId=null;const joystick=$('#joystick');function moveJoy(e){const r=joystick.getBoundingClientRect(),max=r.width*.34;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const len=Math.hypot(x,y);if(len>max){x*=max/len;y*=max/len}joy={x:x/max,y:y/max};$('#stick').style.transform=`translate(${x}px,${y}px)`}
joystick.addEventListener('pointerdown',e=>{if(modal||!started)return;stopAuto();mouseForward=false;joyId=e.pointerId;joystick.setPointerCapture(e.pointerId);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e)});function resetJoy(){joyId=null;joy={x:0,y:0};$('#stick').style.transform=''}joystick.addEventListener('pointerup',resetJoy);joystick.addEventListener('pointercancel',resetJoy);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){closePanel();return}if(modal||!started||e.target.matches('input'))return;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();stopAuto();mouseForward=false;keys.add(e.key.toLowerCase())}if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='m')showMap()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{if(started)persist();stopAuto();keys.clear();resetJoy();drag=null});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(started)persist();stopAuto();keys.clear();resetJoy();drag=null}});

function blocked(x,z,pad=0){return collisions.some(([cx,cz,hx,hz])=>Math.abs(x-cx)<hx+.22+pad&&Math.abs(z-cz)<hz+.22+pad)}
let prev=performance.now(),rendered=false;
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-prev)/1000,.05);prev=now;if(document.hidden)return;
 // One background frame is enough while a reading panel or welcome screen is open.
 if((modal||!started)&&rendered)return;
 const t=now*.001;
 if(started&&!modal){
  if(autoWalking){const moved=advanceWalk([camera.position.x,camera.position.z],route,walkIndex,2.7*dt,blocked);const dx=moved.position[0]-camera.position.x,dz=moved.position[1]-camera.position.z;camera.position.x=moved.position[0];camera.position.z=moved.position[1];walkIndex=moved.index;if(Math.hypot(dx,dz)>.001)yaw=turnTowards(yaw,Math.atan2(-dx,-dz),dt);if(moved.blocked){stopAuto();routeTask=null;toast('步行已停止，請調整方向或重新啟動導覽。')}else if(moved.arrived)arrive();
  }else{let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-joy.y+(mouseForward?1:0);const len=Math.hypot(dx,forward);if(len>1){dx/=len;forward/=len}const [moveX,moveZ]=cameraRelativeMotion(dx,forward,yaw),speed=3.3*dt,nx=THREE.MathUtils.clamp(camera.position.x+moveX*speed,-22.5,22.5),nz=THREE.MathUtils.clamp(camera.position.z+moveZ*speed,-20.5,27);if(!blocked(nx,camera.position.z))camera.position.x=nx;if(!blocked(camera.position.x,nz))camera.position.z=nz;}
  if(targetYaw!==null){yaw=turnTowards(yaw,targetYaw,dt);if(Math.abs(Math.atan2(Math.sin(targetYaw-yaw),Math.cos(targetYaw-yaw)))<.005)targetYaw=null;}
  routeTimer-=dt;if(!autoWalking&&routeTimer<=0){if(routeTask!==(currentTask()?.id??12)||Math.hypot(camera.position.x-routeAnchor[0],camera.position.z-routeAnchor[1])>1.25)rebuildRoute();routeTimer=.35;}
  let closest=4.4;near=null;for(const s of stations.filter(unlocked)){const d=Math.hypot(camera.position.x-s.pos[0],camera.position.z-s.pos[1]);if(d<closest){closest=d;near=s}}const current=currentTask();if(current&&Math.hypot(camera.position.x-current.pos[0],camera.position.z-current.pos[1])<4.4)near=current;if(Math.hypot(camera.position.x,camera.position.z-14)<3.5&&completed.size===11)near='exit';
  hudTimer-=dt;if(hudTimer<=0){guideView();$('#interact').hidden=!near||autoWalking;$('#interact').textContent=near==='exit'?'驗證安全出口 →':near?'Observe':'';$('#locationLabel').textContent=near==='exit'?'安全出口':near?near.area:'農場步道';hudTimer=.12;}
  saveTimer-=dt;if(saveTimer<=0){persist();saveTimer=5;}
  graphics.sample(now);
 }
 camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);nature.tick(t);
 flying.forEach(({b,cx,cz,r,phase,y})=>{b.position.set(cx+Math.cos(t*.45+phase)*r,y+Math.sin(t*1.8+phase)*.2,cz+Math.sin(t*.45+phase)*r);b.rotation.y=-t*.45-phase});try{butterflies.forEach(({root,wings,phase,flightPath,baseY,speed,flapRate})=>{const u=((t*speed+phase/(Math.PI*2))%1+1)%1,point=flightPath.getPointAt(u),tangent=flightPath.getTangentAt(u),lift=Math.sin(t*2.5+phase)*.12,beat=t*flapRate*Math.PI*2+phase;root.position.set(point.x,baseY+lift,point.z);root.rotation.y=Math.atan2(tangent.x,tangent.z);root.rotation.z=.12*Math.sin(t*1.25+phase);root.rotation.x=-.07-.1*Math.sin(t*1.7+phase);for(const {hinge,side,fore} of wings){const lag=fore?0:.14;hinge.rotation.z=side*(.08+(.82+(fore?0:.12))*Math.sin(beat-lag));hinge.rotation.x=.035*Math.sin(beat-lag)}})}catch(e){console.error('Butterfly animation failed',e);const toastEl=document.querySelector('#toast');if(toastEl)toastEl.textContent='蝴蝶動畫錯誤：'+e.message;}demo.rotation.y=.5+Math.sin(t*.12)*.18;demo2.rotation.y=-.6+Math.sin(t*.12)*.18;dancer.position.x=Math.sin(t*1.1)*.65;dancer.position.z=-15+Math.sin(t*2.2)*.5;dancer.rotation.y=Math.atan2(Math.cos(t*1.1),Math.cos(t*2.2));markers.forEach(m=>m.orb.position.y=2.25+Math.sin(t*2+m.s.id)*.07);
 shadowTimer-=dt;if(shadowTimer<=0){renderer.shadowMap.needsUpdate=true;shadowTimer=graphics.shadowInterval;}renderer.render(scene,camera);rendered=true;
}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);rendered=false});
if(Array.isArray(saved.position)&&saved.position.length===2&&saved.position.every(Number.isFinite)&&Math.abs(saved.position[0])<=22.5&&saved.position[1]>=-20.5&&saved.position[1]<=27&&!blocked(...saved.position)){camera.position.set(saved.position[0],1.7,saved.position[1]);yaw=Number.isFinite(saved.yaw)?saved.yaw:0;}else if(completed.size>0){const s=currentTask();const p=s?approach(s):[0,10.8];camera.position.set(p[0],1.7,p[1]);}
